#!/usr/bin/env bash
# ⑤ Codex ⑥ DISAGREE D2·D3·D4 재검증 — 접근 가능한 이름 없는 조작 요소 · 미연결 label · role=tab 포커스 가능 여부 · E1/A1 Enter · 포커스 스타일 · aria-disabled describedby · 대비 계산
B="$HOME/.claude/skills/gstack/browse/dist/browse"
W="C:/Projects/Active/교대근무관리 시스템/시안/2026-09-02-2차HTML"
J() { "$B" js "$1" 2>/dev/null | grep -v "BEGIN\|END" | grep -v '^\s*$'; }
G() { "$B" goto "file:///$W/$1" >/dev/null 2>&1; "$B" wait --load >/dev/null 2>&1; }
"$B" viewport 1440x900 >/dev/null 2>&1

JS_NAMES="(()=>{const vis=e=>{const c=getComputedStyle(e);return c.display!=='none'&&c.visibility!=='hidden';};const txt=e=>[...e.childNodes].map(n=>n.nodeType===3?n.textContent:(n.nodeType===1&&(n.getAttribute('aria-hidden')==='true'||!vis(n))?'':txt(n))).join('');const name=el=>{const lb=el.getAttribute('aria-labelledby');if(lb){const t=lb.split(/\s+/).map(i=>{const x=document.getElementById(i);return x?x.textContent.trim():'';}).join(' ').trim();if(t)return 'labelledby';}const al=el.getAttribute('aria-label');if(al&&al.trim())return 'aria-label';if(el.id){const l=document.querySelector('label[for=\"'+el.id+'\"]');if(l&&l.textContent.trim())return 'for';}if(el.closest('label'))return 'wrap';const tag=el.tagName.toLowerCase();if(tag==='button'||tag==='a'||['tab','button','link'].includes(el.getAttribute('role')||'')){if(txt(el).trim())return 'text';}if(el.title&&el.title.trim())return 'title';return '';};return [...document.querySelectorAll('.state-wrapper')].map(w=>{const ctl=[...w.querySelectorAll('input:not([type=hidden]),select,textarea,button,a[href],[role=tab],[role=button]')].filter(e=>vis(e)&&!e.closest('[aria-hidden=\"true\"]'));const none=ctl.filter(e=>!name(e));const ph=none.filter(e=>e.placeholder);const lbl=[...w.querySelectorAll('label')].filter(l=>vis(l)&&!l.htmlFor&&!l.querySelector('input,select,textarea'));const desc=none.slice(0,60).map(e=>e.tagName.toLowerCase()+(e.type?'['+e.type+']':'')+(e.getAttribute('role')?'@'+e.getAttribute('role'):'')+'{'+(e.placeholder||e.value||txt(e).trim()||e.className.split(' ')[0]).slice(0,14)+'}');return w.id+' 조작요소='+ctl.length+' 이름없음='+none.length+'(placeholder만 '+ph.length+') 미연결label='+lbl.length+' :: '+desc.join(' ');}).join('\n');})()"

JS_TABS="(()=>{const t=[...document.querySelectorAll('[role=tab]')];const f=t.filter(e=>e.tabIndex>=0).length;const tags=[...new Set(t.map(e=>e.tagName.toLowerCase()+'[tabindex='+e.getAttribute('tabindex')+']'))];const tl=document.querySelectorAll('[role=tablist]').length;return 'tablist='+tl+' tab='+t.length+' 포커스가능='+f+' 태그='+tags.join(',')+' | aria-live='+document.querySelectorAll('[aria-live],[role=status],[role=alert]').length;})()"

JS_ADIS="(()=>{return [...document.querySelectorAll('[aria-disabled=\"true\"]')].map(e=>{const d=e.getAttribute('aria-describedby');const ok=d&&d.split(/\s+/).every(i=>document.getElementById(i));const w=e.closest('.state-wrapper');return (w?w.id:'?')+':'+(e.getAttribute('aria-label')||e.textContent.trim()).slice(0,12)+'→'+(d?(ok?'describedby OK':'describedby 끊김('+d+')'):'describedby 없음');}).join(' | ')||'aria-disabled 없음';})()"

JS_FOCUS="(()=>{const lum=c=>{const m=c.match(/\d+(\.\d+)?/g).map(Number);const [r,g,b]=m.slice(0,3).map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);});return 0.2126*r+0.7152*g+0.0722*b;};const cr=(a,b)=>((Math.max(a,b)+0.05)/(Math.min(a,b)+0.05)).toFixed(2);const white=lum('rgb(255,255,255)');const root=getComputedStyle(document.documentElement);const line=root.getPropertyValue('--line').trim(),strong=root.getPropertyValue('--line-strong').trim(),acc=root.getPropertyValue('--accent').trim();const hex=h=>{h=h.replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');return 'rgb('+parseInt(h.slice(0,2),16)+','+parseInt(h.slice(2,4),16)+','+parseInt(h.slice(4,6),16)+')';};const halo='rgb('+Math.round(255+(62-255)*0.15)+','+Math.round(255+(86-255)*0.15)+','+Math.round(255+(182-255)*0.15)+')';const out=['토큰 --line='+line+' 대비(백)='+(line?cr(lum(hex(line)),white):'-')+' · --line-strong='+strong+' 대비='+(strong?cr(lum(hex(strong)),white):'-')+' · --accent='+acc+' 대비='+(acc?cr(lum(hex(acc)),white):'-')+' · halo rgba(62,86,182,.15) 합성='+halo+' 대비='+cr(lum(halo),white)];const probe=(sel,label)=>{const e=document.querySelector(sel);if(!e){out.push(label+': 없음');return;}e.focus();const c=getComputedStyle(e);out.push(label+' focus: outline='+c.outlineStyle+' '+c.outlineWidth+' '+c.outlineColor+' | box-shadow='+c.boxShadow.slice(0,60)+' | border='+c.borderColor+' | 활성='+(document.activeElement===e));e.blur();};probe('.form-input','input');probe('select.form-select','select');probe('button.btn-primary','btn-primary');probe('button.btn-secondary','btn-secondary');probe('.nav-item','nav a');probe('[role=tab]','tab');probe('table tbody tr[tabindex]','tr[tabindex]');return out.join('\n');})()"

JS_ENTER="(()=>{const w=document.getElementById('state-e1')||document.getElementById('state-a1');if(!w)return 'E1/A1 없음';const tr=w.querySelector('table tbody tr');const before=w.innerHTML.length;const vis0=[...w.querySelectorAll('*')].filter(e=>getComputedStyle(e).display!=='none').length;tr.focus();const fo=document.activeElement===tr;tr.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));const after=w.innerHTML.length;const vis1=[...w.querySelectorAll('*')].filter(e=>getComputedStyle(e).display!=='none').length;const src=[...document.scripts].map(s=>s.textContent).join('');return w.id+' 행 tabindex='+tr.getAttribute('tabindex')+' 포커스='+fo+' Enter 후 DOM 변화='+(after-before)+' 표시요소 변화='+(vis1-vis0)+' | 스크립트 Enter 처리='+(/Enter/.test(src))+' 활성요소='+(document.activeElement.tagName)+(document.activeElement.className?'.'+document.activeElement.className.split(' ')[0]:'');})()"

echo "=============== D2 접근 가능한 이름 · 미연결 label (24파일 63상태) ==============="
for p in "$W"/*.html; do f=$(basename "$p"); G "$f"; echo "-- $f"; J "$JS_NAMES"; done
echo "=============== D3 role=tab 포커스 가능 여부 · aria-live (11-operations 1~3) ==============="
for f in 11-operations-1 11-operations-2 11-operations-3; do G "$f.html"; echo "-- $f: $(J "$JS_TABS")"; done
echo "=============== D3 aria-disabled describedby 연결 (24파일) ==============="
for p in "$W"/*.html; do f=$(basename "$p"); G "$f"; r=$(J "$JS_ADIS"); [ "$r" != "aria-disabled 없음" ] && echo "-- $f: $r"; done
echo "=============== D3 E1·A1 Enter → 상세 ==============="
G 06-employees-1.html; J "$JS_ENTER"
G 09-allowance-1.html; J "$JS_ENTER"
echo "=============== D4 포커스 스타일 · 대비 (11-operations-1 / 01-login-1 / 00-shell-1) ==============="
for f in 11-operations-1 01-login-1 00-shell-1; do G "$f.html"; echo "-- $f"; J "$JS_FOCUS"; done
echo DONE
